import * as fs from 'fs';
import * as path from 'path';

// Deep object analysis to understand the structure
function analyzeObject(obj: any, prefix: string = '', depth: number = 0): Set<string> {
  const patterns = new Set<string>();

  if (depth > 10) return patterns; // Prevent infinite recursion

  if (Array.isArray(obj)) {
    patterns.add(`${prefix}[]`);
    if (obj.length > 0) {
      // Analyze first few elements
      for (let i = 0; i < Math.min(3, obj.length); i++) {
        const subPatterns = analyzeObject(obj[i], `${prefix}[${i}]`, depth + 1);
        subPatterns.forEach(p => patterns.add(p));
      }
    }
  } else if (obj !== null && typeof obj === 'object') {
    const keys = Object.keys(obj);
    patterns.add(`${prefix}{${keys.join(', ')}}`);

    for (const key of keys) {
      const value = obj[key];
      const newPrefix = prefix ? `${prefix}.${key}` : key;

      // Add type information
      if (value === null) {
        patterns.add(`${newPrefix}: null`);
      } else if (Array.isArray(value)) {
        patterns.add(`${newPrefix}: array[${value.length}]`);
        if (value.length > 0) {
          const subPatterns = analyzeObject(value, newPrefix, depth + 1);
          subPatterns.forEach(p => patterns.add(p));
        }
      } else if (typeof value === 'object') {
        patterns.add(`${newPrefix}: object`);
        const subPatterns = analyzeObject(value, newPrefix, depth + 1);
        subPatterns.forEach(p => patterns.add(p));
      } else {
        patterns.add(`${newPrefix}: ${typeof value} = ${JSON.stringify(value).slice(0, 50)}`);
      }
    }
  } else {
    patterns.add(`${prefix}: ${typeof obj} = ${JSON.stringify(obj).slice(0, 50)}`);
  }

  return patterns;
}

async function analyzeSmallFile() {
  const dataDir = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

  // Get a small file for detailed analysis
  const files = fs.readdirSync(dataDir).filter(f => f.endsWith('.json'));
  const fileSizes = files.map(f => ({
    name: f,
    size: fs.statSync(path.join(dataDir, f)).size
  })).sort((a, b) => a.size - b.size);

  const smallFile = fileSizes[0];
  console.log(`Analyzing ${smallFile.name} (${(smallFile.size / 1024).toFixed(1)}KB)`);

  const content = fs.readFileSync(path.join(dataDir, smallFile.name), 'utf8');
  const data = JSON.parse(content);

  console.log('\n=== BUNDLE STRUCTURE ===');
  const bundlePatterns = analyzeObject(data, 'bundle', 0);
  Array.from(bundlePatterns).sort().forEach(pattern => {
    if (!pattern.includes('.entry[')) {
      console.log(pattern);
    }
  });

  console.log('\n=== SAMPLE ENTRY STRUCTURE ===');
  if (data.entry && data.entry.length > 0) {
    const sampleEntry = data.entry[0];
    const entryPatterns = analyzeObject(sampleEntry, 'entry', 0);
    Array.from(entryPatterns).sort().forEach(pattern => {
      console.log(pattern);
    });
  }

  console.log('\n=== RESOURCE TYPES AND THEIR KEYS ===');
  const resourceTypeKeys = new Map<string, Set<string>>();

  data.entry.forEach((entry: any, index: number) => {
    const resource = entry.resource;
    if (resource && resource.resourceType) {
      const resourceType = resource.resourceType;
      if (!resourceTypeKeys.has(resourceType)) {
        resourceTypeKeys.set(resourceType, new Set());
      }
      const keys = resourceTypeKeys.get(resourceType)!;
      Object.keys(resource).forEach(key => keys.add(key));
    }
  });

  for (const [resourceType, keys] of resourceTypeKeys.entries()) {
    console.log(`${resourceType}: [${Array.from(keys).sort().join(', ')}]`);
  }

  console.log('\n=== DETAILED RESOURCE ANALYSIS ===');
  // Analyze each resource type in detail
  for (const [resourceType, keys] of resourceTypeKeys.entries()) {
    console.log(`\n--- ${resourceType} ---`);
    const sampleResource = data.entry.find((e: any) => e.resource.resourceType === resourceType)?.resource;
    if (sampleResource) {
      const resourcePatterns = analyzeObject(sampleResource, resourceType, 0);
      Array.from(resourcePatterns).sort().slice(0, 20).forEach(pattern => {
        console.log(pattern);
      });
    }
  }
}

analyzeSmallFile().catch(console.error);

import * as fs from 'fs';
import * as path from 'path';

async function analyzeStructure() {
  const dataDir = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

  // Get a small file for analysis
  const files = fs.readdirSync(dataDir).filter(f => f.endsWith('.json'));
  const fileSizes = files.map(f => ({
    name: f,
    size: fs.statSync(path.join(dataDir, f)).size
  })).sort((a, b) => a.size - b.size);

  const smallFile = fileSizes[0];
  console.log(`Analyzing ${smallFile.name}`);

  const content = fs.readFileSync(path.join(dataDir, smallFile.name), 'utf8');
  const data = JSON.parse(content);

  console.log('\n=== BUNDLE LEVEL ===');
  console.log('Keys:', Object.keys(data));
  console.log('Type:', data.type);
  console.log('ResourceType:', data.resourceType);
  console.log('Entry count:', data.entry.length);

  console.log('\n=== ENTRY STRUCTURE ===');
  const sampleEntry = data.entry[0];
  console.log('Entry keys:', Object.keys(sampleEntry));
  console.log('Request keys:', Object.keys(sampleEntry.request));
  console.log('Resource keys:', Object.keys(sampleEntry.resource));

  console.log('\n=== RESOURCE TYPES ===');
  const resourceTypes = new Map<string, number>();
  data.entry.forEach((entry: any) => {
    const type = entry.resource.resourceType;
    resourceTypes.set(type, (resourceTypes.get(type) || 0) + 1);
  });

  for (const [type, count] of resourceTypes.entries()) {
    console.log(`${type}: ${count}`);
  }

  console.log('\n=== PATIENT RESOURCE ===');
  const patientResource = data.entry.find((e: any) => e.resource.resourceType === 'Patient')?.resource;
  if (patientResource) {
    console.log('Patient keys:', Object.keys(patientResource));
    console.log('Name structure:', JSON.stringify(patientResource.name, null, 2));
    console.log('Address structure:', JSON.stringify(patientResource.address, null, 2));
  }

  console.log('\n=== OBSERVATION RESOURCE ===');
  const observationResource = data.entry.find((e: any) => e.resource.resourceType === 'Observation')?.resource;
  if (observationResource) {
    console.log('Observation keys:', Object.keys(observationResource));
    console.log('Code structure:', JSON.stringify(observationResource.code, null, 2));
    console.log('Value structure:', JSON.stringify(observationResource.valueQuantity || observationResource.valueCodeableConcept || observationResource.valueString, null, 2));
  }

  console.log('\n=== ENCOUNTER RESOURCE ===');
  const encounterResource = data.entry.find((e: any) => e.resource.resourceType === 'Encounter')?.resource;
  if (encounterResource) {
    console.log('Encounter keys:', Object.keys(encounterResource));
    console.log('Class structure:', JSON.stringify(encounterResource.class, null, 2));
    console.log('Period structure:', JSON.stringify(encounterResource.period, null, 2));
  }
}

analyzeStructure().catch(console.error);

