    console.log(`Loading: ${smallestFile}`);

    const content = fs.readFileSync(`${dataDir}/${smallestFile}`, 'utf8');
    const data = JSON.parse(content);

    // Test the first resource (Patient)
    const patientResource = data.entry[0].resource;
    console.log(`Testing Patient resource with resourceType: ${patientResource.resourceType}`);
    console.log(`Patient has these keys: ${Object.keys(patientResource).join(', ')}`);

    const patientResult = Patient.safeParse(patientResource);

    if (patientResult.success) {
      console.log('✅ Patient validation successful!');
    } else {
      console.log('❌ Patient validation failed');
      console.log('Detailed errors:');
      patientResult.error.issues.forEach((issue, index) => {
        console.log(`  ${index + 1}. Path: ${issue.path.join('.')} - ${issue.message}`);
        if (issue.path.length > 0) {
          const value = issue.path.reduce((obj, key) => obj?.[key], patientResource);
          console.log(`     Value: ${JSON.stringify(value)}`);
        }
      });
    }

    // Test another resource type that's failing
    const observationResource = data.entry.find(e => e.resource.resourceType === 'Observation')?.resource;
    if (observationResource) {
      const { Observation } = await import('../schema/fhir-resources');
      console.log(`\nTesting Observation resource...`);

      const obsResult = Observation.safeParse(observationResource);
      if (obsResult.success) {
